import crypto from 'crypto';

// Millisecond and rand_a counter of the last id generated by this process (RFC 9562 §6.2, method 1).
let lastMs = -1;
let counter = 0;

/**
 * Generates an RFC 9562 compliant UUIDv7 string.
 * Format: 48-bit Unix timestamp (ms) | 12-bit random/counter | 2-bit variant | 62-bit random
 * Ensures chronological sortability and high entropy.
 */
export function generateUuidV7(timestampMs: number = Date.now()): string {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);

  // 12-bit counter, seeded randomly below 0x800 per millisecond and +1 per id within it: ids generated in the
  // same millisecond sort in generation order (ORDER BY created_at, id relies on it for same-transaction rows).
  // ponytail: wraps after 2048+ ids in one millisecond; borrow the next millisecond if bulk generation needs it.
  counter = timestampMs === lastMs ? (counter + 1) & 0xfff : ((bytes[6]! & 0x07) << 8) | bytes[7]!;
  lastMs = timestampMs;

  // 48-bit timestamp in milliseconds
  bytes[0] = (timestampMs / 0x10000000000) & 0xff;
  bytes[1] = (timestampMs / 0x100000000) & 0xff;
  bytes[2] = (timestampMs / 0x1000000) & 0xff;
  bytes[3] = (timestampMs / 0x10000) & 0xff;
  bytes[4] = (timestampMs / 0x100) & 0xff;
  bytes[5] = timestampMs & 0xff;

  // Version 7: set 4 bits of octet 6 to 0111, followed by the 12-bit counter
  bytes[6] = 0x70 | (counter >> 8);
  bytes[7] = counter & 0xff;

  // Variant 1: set 2 most significant bits of octet 8 to 10
  bytes[8] = (bytes[8]! & 0x3f) | 0x80;

  // Format as standard UUID string: 8-4-4-4-12
  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

export function isValidUuid(id: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id);
}
